      FT_UShort       num_glyph_layers;


      error = sfnt->load_colr_layer( face,
                                     glyph_index,
                                     &glyph_layers,
                                     &num_glyph_layers );
      if ( error )
        return error;

      if ( !glyph->internal->color_layers )
      {
